\label{p1}
  Let $x,y,z\in H$ and $a,b\in\mathbb{R}$. Then
  \begin{equation}
    \begin{split}
       ||(1+a)x-(a-b)y-bz||^2 =&(1+a)||x||^2-(a-b)||y||^2-b||z||^2\\\notag
                               & +(1+a)(a-b)||x-y||\\\notag
                               & +b(1+a)||x-z||^2-b(a-b)||y-z||^2 .\\\notag
    \end{split}
  \end{equation}

\label{p2}
  Let $C$ be a nonempty closed subset of a real Hilbert space $H$. $\forall v\in H$ and $\forall z\in C$, we have
  \begin{equation}
    z = P_{C}v \Leftrightarrow \langle v-z,z-y\rangle\geq0, \forall y \in C.\notag
  \end{equation}

\label{u-v}
  The following identities hold for all $u,v\in H$ :
    \begin{equation}
      2\langle u,v \rangle =\|u\|^2+\|v\|^2-\|u-v\|^2=\|u+v\|^2-\|u\|^2-\|v\|^2.\notag
    \end{equation}

Under the (i)–(iv) of Assumption 1, the sequence ${\lambda_{k}}$ generated Algorithm \ref{algo:myalg} satisfying 
  \begin{equation}\label{minlambda}
    \min\{\frac{l\mu}{L},\lambda_{0}\}\leq\lambda_{k}\leq\lambda_{0}.
  \end{equation}

Firstly, it is obvious that ${\lambda^{(1)}_{k}}$ is a monotonically decreasing sequence. Since $A$ is a Lipschitz continuous mapping with constant $L>0$,  in the case of $Aw_k-Ay_k\neq0$, we have
    \begin{equation}
      \frac{{\mu \left\| {{w_k} - {y_k}} \right\|}}{{||A{w_k} - A{y_k}||}} \ge \frac{\mu }{L}\frac{{\left\| {{w_k} - {y_k}} \right\|}}{{\left\| {{w_k} - {y_k}} \right\|}} = \frac{\mu }{L} \notag 
    \end{equation}

Let $q\in S_{D}$. First of all, we estimate  $||x_{k+1}-q||^2$. It can be obtained from the definition of $x_{k+1}$ that:
\begin{align}\label{l42p1}
||x_{k+1}-q||^2 =&||y_{k}-\lambda_{k}(Ay_{k}-Aw_{k})-q||^2
\notag\\
=&||y_{k}-q||^2 +\lambda_{k}^2||Ay_{k}-Aw_{k}||^2-2\lambda_{k}\langle Ay_{k}-Aw_{k},y_{k}-q\rangle
\notag\\
=&||w_{k}-q||^2+||w_{k}-y_{k}||^2+2\langle y_{k}-w_{k},w_{k}-q\rangle+\lambda_{k}^2||Ay_{k}-Aw_{k}||^2
\notag\\
&-2\lambda_{k}\langle Ay_{k}-Aw_{k},y_{k}-q\rangle
\notag\\
=&||w_{k}-q||^2+||w_{k}-y_{k}||^2-2\langle y_{k}-w_{k},y_{k}-w_{k}\rangle+
2\langle y_{k}-w_{k},y_{k}-q\rangle
\notag\\
&+\lambda_{k}^2||Ay_{k}-Aw_{k}||^2-2\lambda_{k}\langle Ay_{k}-Aw_{k},y_{k}-q\rangle
\notag\\
=&||w_{k}-q||^2-||w_{k}-y_{k}||^2+2\langle y_{k}-w_{k},y_{k}-q\rangle+\lambda_{k}^2||Ay_{k}-Aw_{k}||^2
\notag\\
&-2\lambda_{k}\langle Ay_{k}-Aw_{k},y_{k}-q\rangle.
\end{align}
From the definition of $y_{k}$, and the fact that $S_{D}\subset C$,

 it can be obtained by Lemma \ref{p2} that:
$$
  \langle w_{k}-\lambda_{k}Aw_{k}-y_{k},y_{k}-q\rangle\geq0,
$$
that is
\begin{equation}\label{l42p2}
  \langle y_k-w_k,y_k-q\rangle\leq-\lambda_k\langle Aw_k,y_k-q\rangle.
\end{equation}
Appling (\ref{l42p2}) to (\ref{l42p1}), we will have
\begin{align}\label{l43p3}
||x_{k+1}-q||^2 \leq & ||w_{k}-q||^2-||w_{k}-y_{k}||^2-2\lambda_{k}\langle Aw_{k},y_{k}-q\rangle
\notag\\
&+\lambda_{k}^2||Ay_{k}-Aw_{k}||^2-2\lambda_{k}\langle Ay_{k}-Aw_{k},y_{k}-q\rangle
\notag\\
=&||w_{k}-q||^2-||w_{k}-y_{k}||^2+\lambda_{k}^2||Ay_{k}-Aw_{k}||^2
\notag\\
&-2\lambda_{k}\langle Ay_{k},y_{k}-q \rangle.
\end{align}
Since $q\in S_{D}, \lambda_{k}>0$ and $y_{k}\in C$, we have that 
\begin{equation}\label{l42p4}
  \lambda_{k}\langle Ay_{k},y_{k}-q \rangle \geq0.
\end{equation}
Therefore, from (\ref{l43p3}) we can have
\begin{equation}\label{l42p5}
 ||x_{k+1}-q||^2 \leq ||w_{k}-q||^2-||w_{k}-y_{k}||^2+\lambda_{k}^2||Ay_{k}-Aw_{k}||^2.
\end{equation}
From the definition of  $\lambda_{k}$, if ${Aw_{k}-Ay_{k}}\neq0$, then we have
$$
\lambda_{k}^{(1)} = \min\{\frac{\mu||w_{k}-y_{k}||}{||Aw_{k}-Ay_{k}||},\lambda_{k-1}\}
$$
which means:
$$
\lambda_{k}^{(1)} \leq\frac{\mu||w_{k}-y_{k}||}{||{Aw_{k}-Ay_{k}}||},
$$
$$
\lambda_{k}^{(1)}||{Aw_{k}-Ay_{k}}||\leq\mu||w_{k}-y_{k}||.
$$
Also, we have $\lambda_{k}^{(2)}\left\|A w_{k}-A y_{k}\right\| \leq \mu\left\|w_{k}-y_{k}\right\|$. Therefore,
\begin{equation}\label{l42p6}
  \lambda_{k}\left\|A w_{k}-A y_{k}\right\| \leq \mu\left\|w_{k}-y_{k}\right\|.
\end{equation}
Substituting  (\ref{l42p6}) into (\ref{l42p5}), we have
\begin{align}\label{l42p7}
  ||x_{k+1}-q||^2 \leq&||w_{k}-q||^2-||w_{k}-y_{k}||^2+\mu^2||w_{k}-y_{k}||^2
  \notag\\
  =& ||w_{k}-q||^2-(1-\mu^2)||w_{k}-y_{k}||^2.
\end{align}
Observe that
\begin{align}
||x_{k+1}-y_{k}||=&||y_{k}-\lambda_{k}(Ay_{k}-Aw_{k})-y_{k}|| \notag\\
  = & \lambda_{k}||Ay_{k}-Aw_{k}||\notag \\
  \leq & \mu||w_{k}-y_{k}||,\notag
\end{align}
and
\begin{align}\label{l42p8}
||x_{k+1}-w_{k}||\leq &||x_{k+1}-y_{k}||+||w_{k}-y_{k}||\notag \\
  \leq & \mu||w_{k}-y_{k}||+||w_{k}-y_{k}|| \notag\\
  = &  (1+\mu)||w_{k}-y_{k}||.
\end{align}
Hence, using (\ref{l42p8}) into (\ref{l42p7}), we obtain that
\begin{equation}\label{l42p9}
  -||w_{k}-y_{k}||^2\leq-\frac{1}{(1+\mu)^2}||x_{k+1}-w_{k}||^2.
\end{equation}
Applying (\ref{l42p9}) into (\ref{l42p7}), we have
\begin{equation}\label{l42p10}
  ||x_{k+1}-q||^2 \leq ||w_{k}-q||^2 - (\frac{1-\mu}{1+\mu})||x_{k+1}-w_{k}||^2.
\end{equation}
Also, 
\begin{align}
  w_{k}-q = & x_{k}+\alpha(x_{k}-x_{k-1})+\beta(x_{k-1}-x_{k-2})-q\notag\\
  = & (1+\alpha)(x_{k}-q)-(\alpha-\beta)(x_{k-1}-q)-\beta(x_{k-2}-q).\notag
\end{align}

Using Lemma \ref{p1}, we get
\begin{align}\label{wn-q}
  ||w_{k}-q||^2 =& ||(1+\alpha)(x_{k}-q)-(\alpha-\beta)(x_{k-1}-q)-\beta(x_{k-2}-q)||^2 \notag \\
  = & (1+\alpha)||x_{k}-q||^2-(\alpha-\beta)||x_{k-1}-q||^2-\beta||x_{k-2}-q||^2 \notag\\
   & +(1+\alpha)(\alpha-\beta)||x_{k}-x_{k-1}||^2+\beta(1+\alpha)||x_{k}-x_{k-2}||\notag \\
   & -\beta(\alpha-\beta)||x_{k-1}-x_{k-2}||^2.
\end{align}
Furthermore, it can be obtained that
\begin{align}\label{xn+1-wn}
||x_{k+1}-w_{k}||^{2}=&\|x_{k+1}-[x_k+\alpha(x_k-x_{k-1})+\beta(x_{k-1}-x_{k-2})]\|^2  \notag \\
    =&\|x_{k+1}-x_{k}-\alpha(x_{k}-x_{k-1})-\beta(x_{k-1}-x_{k-2})\|^{2}\notag\\
    =&\|x_{k+1}-x_{k}\|^{2}-2\alpha\langle x_{k+1}-x_{k},x_{k}-x_{k-1}\rangle-2\beta\langle x_{k+1}-x_{k},x_{k-1}-x_{k-2}\rangle \notag\\
    &+\alpha^2||x_{k}-x_{k-1}||^2+2\alpha\beta\langle x_{k}-x_{k-1},x_{k-1}-x_{k-2}\rangle+\beta^2||x_{k-1}-x_{k-2}||\notag\\
    \geq&\|x_{k+1}-x_{k}\|^{2}-\alpha\|x_{k+1}-x_{k}\|^{2}-\alpha\|x_{k}-x_{k-1}\|^{2}+\alpha^{2}\|x_{k}-x_{k-1}\| \notag\\
    &-|\beta|\alpha\|x_{k}-x_{k-1}\|^2-|\beta|\alpha\|x_{k-1}-x_{k-2}\|^{2}+\beta^{2}\|x_{k-1}-x_{k-2}\|^{2} \notag\\
    &-|\beta|\|x_{k+1}-x_k\|^2-|\beta|\|x_{k-1}-x_{k-2}\|^2 \notag\\
    =&(1-|\beta|-\alpha)\|x_{k+1}-x_{k}\|^{2}+(\alpha^{2}-\alpha-|\beta|\alpha)\|x_{k}-x_{k-1}\|^{2} \notag\\
    &+(\beta^{2}-|\beta|-|\beta|\alpha)\|x_{k-1}-x_{k-2}\|^{2}.
\end{align}
Applying (\ref{wn-q}) and (\ref{xn+1-wn}) with (\ref{l42p10}) and note that $\beta <0$ we have
\begin{align}
||x_{k+1}-q||^{2}\leq&(1+\alpha)\|x_{k}-q\|^{2}-(\alpha-\beta)\|x_{k-1}-q\|^{2}-\beta\|x_{k-2}-q\|^{2}\notag\\
    &+(1+\alpha)(\alpha-\beta)\|x_k-x_{k-1}\|^2+\beta(1+\alpha)\|x_k-x_{k-2}\|^2\notag\\
    &-\beta(\alpha-\beta)\|x_{k-1}-x_{k-2}\|^2-\Big(\frac{1-\mu}{1+\mu}\Big)(1-|\beta|-\alpha)\|x_{k+1}-x_k\|^2\notag\\
    &-\Big(\frac{1-\mu}{1+\mu}\Big)(\alpha^2-\alpha-|\beta|\alpha)\|x_k-x_{k-1}\|^2\notag\\
    &-\Big(\frac{1-\mu}{1+\mu}\Big)(\beta^2-|\beta|-|\beta|\alpha)\|x_{k-1}-x_{k-2}\|^2\notag\\
    \leq &(1+\alpha)\|x_k-q\|^2-(\alpha-\beta)\|x_{k-1}-q\|^2-\beta\|x_{k-2}-q\|^2+\Big[(1+\alpha)(\alpha-\beta)\notag\\
    &-\Big(\frac{1-\mu}{1+\mu}\Big)(\alpha^2-\alpha+\beta\alpha)\Big]\|x_k-x_{k-1}\|^2\notag\\
    &-[\beta(\alpha-\beta)+\Big(\frac{1-\mu}{1+\mu}\Big)(\beta^2+\beta+\beta\alpha)]\|x_{k-1}-x_{k-2}\|^2\notag\\
    &-\Big(\frac{1-\mu}{1+\mu}\Big)(1+\beta-\alpha)\|x_{k+1}-x_k\|^2.
\end{align}
By rearranging the inequality above we obtain that:
\begin{align}\label{Rearange}
&\|x_{k+1}-q\|^{2}-\alpha\|x_{k}-q\|^{2}-\beta\|x_{k-1}-q\|^{2}+\Big(\frac{1-\mu}{1+\mu}\Big)(1+\beta-\alpha)\|x_{k+1}-x_{k}\|^{2}\notag\\
&\leq\|x_{k}-q\|^{2}-\alpha\|x_{k-1}-q\|^{2}-\beta\|x_{k-2}-q\|^{2}+\Big(\frac{1-\mu}{1+\mu}\Big)(1+\beta-\alpha)\|x_{k}-x_{k-1}\|^{2}\notag\\
&+[(1+\alpha)(\alpha-\beta)-\big(\frac{1-\mu}{1+\mu}\big)(\alpha^2-2\alpha+\beta\alpha+\beta+1)\big]\|x_k-x_{k-1}\|^2\notag\\
&-[\beta(\alpha-\beta)+\left(\frac{1-\mu}{1+\mu}\right)(\beta^2+\beta+\beta\alpha)]\|x_{k-1}-x_{k-2}\|^2.
\end{align}
Now, let  
$$
\Gamma_{k} = \|x_k-q\|^2-\alpha\|x_{k-1}-q\|^2-\beta\|x_{k-2}-q\|^2+\left(\frac{1-\mu}{1+\mu}\right)(1+\beta-\alpha)\|x_k-x_{k-1}\|^2.
$$
Then we can rewrite (\ref{Rearange}) as 
\begin{align}\label{l42p12}
  \Gamma_{k+1} \leq & \Gamma_k+[(1+\alpha)(\alpha-\beta)
   -\left(\frac{1-\mu}{1+\mu}\right)(\alpha^2-2\alpha+\beta\alpha+\beta+1)]\|x_k-x_{k-1}\|^2 \notag\\
  & -[\beta(\alpha-\beta)+\left(\frac{1-\mu}{1+\mu}\right)(\beta^2+\beta+\beta\alpha)]\|x_{k-1}-x_{k-2}\|^2. 
\end{align}
{\bf Claim:} $\Gamma_{k}\geq0$, $\forall k>1$. Since
\begin{align}\label{Tn=}
\Gamma_{k}
=&\|x_{k}-q\|^{2}-\alpha\|x_{k-1}-q\|^{2}-\beta\|x_{k-2}-q\|^{2}+\left(\frac{1-\mu}{1+\mu}\right)(1+\beta-\alpha)\|x_{k}-x_{k-1}\|^{2} \notag\\
\geq&\|x_{k}-q\|^{2}-2\alpha\|x_{k}-x_{k-1}\|^{2}-2\alpha\|x_{k}-q\|^{2}-\beta\|x_{k-2}-q\|^{2} \notag\\
&+\left(\frac{1-\mu}{1+\mu}\right)(1+\beta-\alpha)\|x_k-x_{k-1}\|^2 \notag\\
=&(1-2\alpha)\|x_{k}-q\|^{2}+\left[\left(\frac{1-\mu}{1+\mu}\right)(1+\beta-\alpha)-2\alpha\right]\|x_{k}-x_{k-1}\|^{2} \notag\\
&-\beta||x_{k-2}-q||^2.
\end{align}
From Assumption 2, we have that $\alpha<\frac{1}{2},\beta\leq0,\frac{\alpha(3+\mu)}{1-\mu}-1\leq\beta$ and $0<\alpha<\frac{1-\mu}{3+\mu}$, it can be conclude that $\Gamma_{k}\geq 0$, $\forall k>1$. Let









\begin{align}
  k_{1} :=& -[(1+\alpha)(\alpha-\beta)-\left(\frac{1-\mu}{1+\mu}\right)(\alpha^2-2\alpha+\beta\alpha+\beta+1)] \notag\\
  k_{2} :=& -[(1+\alpha)(\alpha-\beta)-\left(\frac{1-\mu}{1+\mu}\right)(\alpha^2-2\alpha+\beta\alpha+\beta+1)-\beta(\alpha-\beta) -\left(\frac{1-\mu}{1+\mu}\right)(\beta^2+\beta+\beta\alpha)]. \notag\\
\end{align}
Thus, we deduce from (\ref{l42p12}) that
\begin{equation}\label{gamma-gamma}
\Gamma_{k+1}-\Gamma_n\leq k_1(\|x_{k-1}-x_{k-2}\|^2-\|x_k-x_{k-1}\|^2)-k_2\|x_{k-1}-x_{k-2}\|^2.
\end{equation}
From Assumption 2(b), 
\begin{equation}
  \max\Big\{2\alpha (\frac{1-\mu}{3+\mu})-(1-\alpha),\frac{1}{2}[\alpha(1+\mu)-(\frac{(1-\mu)(1-\alpha)^2}{1+\alpha})]\Big\}<\beta\leq0, \notag 
\end{equation}
which implies that 
\begin{equation}\label{2bchange}
  \frac{1}{2}\left[\alpha(1+\mu)-\frac{(1-\mu)(1-\alpha)^2}{1+\alpha}\right]<\beta,
\end{equation}
which can conclude that $k_{1}>0$. \\
By Assumption 2(c) we can have $k_{2}>0$, thus, (\ref{gamma-gamma}) can be rewritten as
\begin{equation}\label{gammak1}
\Gamma_{k+1}+k_1\|x_k-x_{k-1}\|^2\leq\Gamma_k+k_1\|x_{k-1}-x_{k-2}\|^2-k_2\|x_{k-1}-x_{k-2}\|^2.
\end{equation}
Letting $\Gamma_k^{\prime}=\Gamma_k+k_1\|x_{k-1}-x_{k-2}\|^2.$ Then, $\Gamma_k^{^{\prime}}\geq0$,  $\forall k\geq1$. Therefore, we deduce from (\ref{gammak1}) that 
\begin{equation}\label{gamma'}
  \Gamma_{k+1}^{'}\leq\Gamma_{k}^{'},
\end{equation}
which implies that  the sequence ${\Gamma_{k+1}^{'}}$ is decreasing and bounded from below
and thus $\lim\limits_{n\rightarrow\infty}\Gamma_{k}^{'}$ exists. \\
Hence, by rearranging (\ref{gammak1}) and letting $k$ approach infinity, we have

\begin{equation}\label{lim0}
\lim_{k\rightarrow\infty}k_{2}||x_{k-1}-x_{k-2}||^2=0 \implies\lim_{k\rightarrow\infty}||x_{k-1}-x_{k-2}||=0.
\end{equation}
It is easy to see that 
\begin{align}\label{xn1wn}
\|x_{k+1}-w_{k}\|
=&\|x_{k+1}-x_{k}-\alpha(x_{k}-x_{k-1})-\beta(x_{k-1}-x_{k-2})\| \notag\\
\leq&\|x_{k+1}-x_{k}\|+\alpha\|x_{k}-x_{k-1}\|+\beta\|x_{k-1}-x_{k-2}\|.
\end{align} 
Consequently, by (\ref{lim0}) we have 

\begin{align}\label{xn1wn2}
\lim_{k\rightarrow\infty}\|x_{k+1}-w_{k}\|=0.

\end{align} 
Furthermore,
\begin{align}
\|x_{k}-w_{k}\|
=&\|x_{k}-x_{k}-\alpha(x_{k}-x_{k-1})-\beta(x_{k-1}-x_{k-2})\|\notag\\
\leq&\alpha\|x_{k}-x_{k-1}\|+\beta\|x_{k-1}-x_{k-2}\|\rightarrow0, k\rightarrow\infty.
\end{align}
Observe that
\begin{align}\label{xn1wn->0}
\|x_{k+1}-w_{k}\|=&\quad\|y_{k}-\lambda_{k}(Ay_{k}-Aw_{k})-w_{k}\|\notag\\
\geq&\quad\|y_{k}-w_{k}\|-\lambda_{k}\|Ay_{k}-Aw_{k}\|\notag\\
\geq&\quad\|y_{k}-w_{k}\|-\mu\|y_{k}-w_{k}\|\notag\\
=&\quad(1-\mu)\|y_{k}-w_{k}\|.
\end{align}
Using (\ref{xn1wn2} )we deduce from (\ref{xn1wn->0}) that 

\begin{equation}\label{wnyn->0}
\lim_{k\rightarrow\infty}\|w_k-y_k\| = 0.
\end{equation}
Also,
\begin{equation}\label{xnyn}
\|x_k-y_k\|\leq\|x_k-w_k\|+\|w_k-y_k\|\to0, k\to\infty.
\end{equation}
Due to the existence of the limit $\Gamma_{k}^{'}$ and (\ref{lim0}), 
we can obtain that the limit of $\Gamma_{k}$  also exists and therefore, the sequence $\{\Gamma_{k}\}$ is bounded.\newline
Since $\lim\limits_{k\rightarrow\infty}||x_{k+1}-x_{k}||=0$, from the definition of $\Gamma_{k}$ we can get that 
\begin{equation}\label{lim2}
  \lim_{k\to\infty}(\|x_k-q\|^2-\alpha\|x_{k-1}-q\|^2-\beta\|x_{k-2}-q\|^2)
\end{equation}
exists. Due to the boundedness of $\{\Gamma_{k}\}$, we have from (\ref{Tn=}) that $\{x_{k}\}$ is bounded and $\{y_{k}\}$ and $\{w_{k}\}$ are bounded.

\label{case}
Let $\{x_{k}\}$ be the sequence generated by algorithm \ref{algo:myalg}, satisfying Assumptions 1(i)-(iv) and Assumptions 2(a)-(c), and assuming that $\lim \limits_{k\rightarrow\infty}w_{k}-y_{k} = 0$. 
If $v^*$is one of the weakly clustered points of ${y_k}$, then we have at least one of the following: $v^*\in S_D$ or $Av^*= 0$.

From the lemma (\ref{lm42}) above, it can be concluded that $\{y_{k}\}$ is bounded. Therefore let $v^*$ be a weak cluster point of $\{y_{k}\}$.
  Hence, we denote $\{y_{k_{j}}\}$ as a subsequence of $\{y_{k}\}$ such that $y_{k_{j}}\rightharpoonup v^*\in C$.

  Now we discuss in two cases.
    \begin{case}
      First, we assume that $\lim \limits_{k\rightarrow\infty}||Ay_{k_{j}}||=0$. Consequently, 
      $\lim \limits_{k\rightarrow\infty}||Ay_{k_{j}}||=\liminf \limits_{k\rightarrow\infty}||Ay_{k_{j}}||=0$

      Through the assumption above that $y_{k_{j}}\rightharpoonup v^*\in C$ and $A$ satisfies Assumption 1(iii), that is
        \begin{equation}\label{0<avlim}
          0\leq||Av^*||\leq\liminf \limits_{k\rightarrow\infty}||Ay_{k_{j}}||=0.
        \end{equation}
      Which just implies that $Av^*=0$.
    \end{case}
    Now we consider the another situation.

    \begin{case}
        If\quad $\limsup\limits_{k\to\infty}\|Ay_{k_j}\|>0$. Without loss of generality, we take $\lim\limits_{k\to\infty}\|Ay_{k_j}\|=M_{1}>0$. It then follows that there exists a $\mathbf{K}\in\mathbb{K}$ such that $\|Ay_{k_j}\|>\frac{M_{1}}{2}$ for all $k\geq \mathbf{K}$ Since $y_{k_{j}}=P_C(w_{k_{j}}-\lambda_{k_{j}}Aw_{k_{j}})$, we have 

        $$
        \langle w_{k_{j}}-\lambda_{k_{j}}Aw_{k_{j}}-y_{k_{j}},x-y_{k_{j}}\rangle \leq 0,
        $$
        \begin{equation}\label{ca2}
          \frac{1}{\lambda_{k_{j}}}\langle w_{k_{j}}-y_{k_{j}},x-y_{k_{j}} \rangle
          +\langle Aw_{k_{j}},y_{k_{j}}-w_{k_{j}}\rangle\leq\langle Aw_{k_{j}},x-w_{k_{j}} \rangle.
        \end{equation}
      For the weak convergence of $w_{k_{j}}$, $w_{k_{j}}$ is bounded. Then, for the $A$ Lipschitz continuous, $Aw_{k_{j}}$ is bounded. By (\ref{wnyn->0}) we can get that 
      $$
      \|w_{k_{j}}-y_{k_{j}}\|\to0,k\to\infty;
      $$
      therefore $\|y_{k_{j}}\|$ is also bounded and through the Lemma(\ref{minlambda}) we get that 
      $\lambda_{k_{j}}\geq min\{\frac{l\mu}{L},\lambda_{0}\}$. Passing (\ref{ca2}) to the limit as 
      $k\rightarrow\infty$, that is
      \begin{equation}\label{liminf}
        \liminf \limits_{k\rightarrow\infty}\langle Aw_{k_{j}},x-w_{k_{j}} \rangle \geq 0,\forall x \in C.
      \end{equation}
      Observe that
      \begin{align}\label{aynkxynk}
        \langle Ay_{k_{j}},x-y_{k_{j}}\rangle  
        =& \langle Ay_{k_{j}}-Aw_{k_{j}},x-w_{k_{j}}\rangle+\langle Aw_{k_{j}},x-w_{k_{j}}\rangle\notag\\
        &+\langle Ay_{k_{j}},w_{k_{j}}-y_{k_{j}}\rangle.
      \end{align}  
      Thus we can get  $\lim \limits_{k\rightarrow\infty}||Aw_{k_{j}}-Ay_{k_{j}}||=0$, for the 
      $\lim \limits_{k\rightarrow\infty}||w_{k_{j}}-y_{k_{j}}||=0$ and the $L$ -Lipschitz continuity on $H$ of $A$.
      Together with (\ref{liminf}) and (\ref{aynkxynk}) which implies that 
      \begin{equation}\label{liminfaynk}
        \lim \limits_{k\rightarrow\infty}\langle Ay_{k_{j}},x-y_{k_{j}}\rangle \geq 0.
      \end{equation}
      If we suppose that $\limsup\limits_{k\rightarrow\infty}\langle Ay_{k_{j}},x-y_{k_{j}}\rangle>0$, then there exists a subsequence denoted by $y_{n_{k_{j}}}$ 
      such that $\lim\limits_{j\rightarrow\infty}\langle Ay_{n_{k_{j}}},x-y_{n_{k_{j}}} \rangle > 0$,
      that is there exists $j_{0}\in \mathbb{K}$ such that 
      \begin{equation}\label{liminfaynk}
        \langle Ay_{n_{k_{{j}}}},x-y_{k_{j}}\rangle \geq 0, \forall j > j_{0}.
      \end{equation}
      Through the quasimonotonicity(\ref{def}) of $A$, we get $\langle Ax,x-y_{n_{k_{j}}}\rangle\geq0$, as $j\rightarrow\infty$, we conclude that $v^*\in S_{D}$
      On the other hand we suppose that if $\limsup\limits_{k\rightarrow\infty}\langle Ay_{k_{j}},x-y_{k_{j}}\rangle=0$, plus (\ref{liminf}) implies that 
      \begin{equation}\label{liminfaynkcase2}
        \lim \limits_{k\rightarrow\infty}\langle Ay_{k_{j}},x-y_{k_{j}}\rangle = 0.
      \end{equation}
      Let $\epsilon_{k}:= |Ay_{k_{j}},x-y_{k_{j}}|+\frac{1}{k+1}$. Thus we obtain that 
      \begin{equation}\label{axye}
        \langle Ay_{k_{j}},x-y_{k_{j}}\rangle + \epsilon_{k} > 0, \forall k\geq 1.
      \end{equation}
      Furthermore, for each $k\geq \mathbf{K}$ we can get $Ay_{k_{j}}\neq0$. Defining that 
      \begin{equation}\label{q}
        r_{k_{j}} = \frac{Ay_{k_{j}}}{||Ay_{k_{j}}||^2}, \forall~k\geq \mathbf{K}, \notag
      \end{equation}
      then $\langle Ay_{k_{j}},r_{k_{j}}\rangle=1$ for each $k\geq \mathbf{K}$.
      Thus we can conclude from (\ref{axye}) that,
