Suppose $w_{w}(x_{k})$ is a set of weak cluster points of $\{x_{k}\}$. Which is 
    $$
    w_{w}(x_{k})\subset S_{D}.
    $$
  We take $v^*\in w_{w}(x_{k})$.Therefore, there exists a subsequence $\{x_{n_{k}}\}\subset\{x_{k}\}$ such that $\{x_{n_{k}}\}\rightarrow v^*$, 
  $k \rightarrow\infty$. Since $C$ is weakly closed, we have that $v^*\in C$.
  Furthermore, we can conclude that $Av^*\neq0$ for $Ax\neq0, ~\forall x\in C $.
  By Lemma (\ref{case}), we have $v^*\in S_{D}$. Hence $w_{w}(x_{k})\subset S_{D}$.
  By Lemma (\ref{lm42}), $\lim\limits_{n\rightarrow\infty}\Gamma_{k}$ exists and 
  $\lim\limits_{n\rightarrow\infty}||x_{k+1}-x_{k}||=0$, we have 
  \begin{equation}\label{lim}
   \lim\limits_{n\rightarrow\infty}[||x_{k}-q||^2-\alpha||x_{k-1}-q||^2-\beta||x_{k-1}-q||^2]
  \end{equation}
  exists for $\forall q \in S_{D}$.

  Next we show that $x_{k}\rightharpoonup x^*\in S_{D}$. Let $\{x_{n_{j}}\}$ and $\{x_{n_{m}}\}$ both $\subset \{x_{k}\}$ such that $x_{n_{j}}\rightharpoonup v^*, j\rightarrow\infty$ and $x_{n_{m}}\rightharpoonup x^*, m\rightarrow\infty$.

  Then we show that $x^*=v^*$, using (\ref{u-v}) observe that 
  \begin{equation}\label{2<>1}
    2\langle x_{k}, x^*-v^*\rangle = ||x_{k}-v^*||^2-||x_{k}-x^*||^2-||v^*||^2+||x^*||^2;
  \end{equation}

  \begin{equation}\label{2<>2}
    2\langle x_{k-1}, x^*-v^*\rangle = ||x_{k-1}-v^*||^2-||x_{k-1}-x^*||^2-||v^*||^2+||x^*||^2;
  \end{equation}
  and
  \begin{equation}\label{2<>3}
    2\langle x_{k-2}, x^*-v^*\rangle = ||x_{k-2}-v^*||^2-||x_{k-2}-x^*||^2-||v^*||^2+||x^*||^2;
  \end{equation}
  Therefore, 
  \begin{equation}\label{2<>4}
    2\langle -\alpha x_{k-1}, x^*-v^*\rangle = -\alpha||x_{k-1}-v^*||^2+\alpha||x_{k-1}-x^*||^2+\alpha||v^*||^2-\alpha||x^*||^2;
  \end{equation}
  and
  \begin{equation}\label{2<>5}
    2\langle -\beta x_{k-1}, x^*-v^*\rangle = -\beta||x_{k-1}-v^*||^2+\beta||x_{k-1}-x^*||^2+\beta||v^*||^2-\beta||x^*||^2;
  \end{equation}
  Addition of (\ref{2<>1}), (\ref{2<>4}) and (\ref{2<>5}) gives
  \begin{align}\label{addi}
     2\langle x_k-\alpha x_{k-1}-\beta x_{k-2},x^*-v^*\rangle \notag
     =& \left(\|x_k-v^*\|^2-\alpha\|x_{k-1}-v^*\|^2-\beta\|x_{k-2}-v^*\|^2\right) \notag \\
     &-(\|x_k-x^*\|^2-\alpha\|x_{k-1}-x^*\|^2-\beta\|x_{k-2}-x^*\|^2)  \notag\\
     &+(1-\alpha-\beta)(\|x^*\|-\|v^*\|^2). 
  \end{align}
  Through (\ref{lim2}) we know that
  \begin{equation}\label{lim23}
  \lim\limits_{n\to\infty}(\|x_k-x^*\|^2-\alpha\|x_{k-1}-x^*\|^2-\beta\|x_{k-2}-x^*\|^2)
  \end{equation}
  exists, and 
  \begin{equation}\label{lim24}
  \lim\limits_{n\to\infty}(\|x_k-v^*\|^2-\alpha\|x_{k-1}-x^*\|^2-\beta\|x_{k-2}-x^*\|^2)
  \end{equation}
  also exists, which implies with (\ref{addi}) that 
  $\lim\limits_{n\to\infty}\langle x_{k}-\alpha x_{k-1}-\beta x_{k-2},x^*-v^* \rangle$ exists.

  Consequently,
  \begin{align}\label{last}
  \langle v^*-\alpha v^*-\beta v^*, x^*-v^* \rangle
    =&\lim\limits_{j\rightarrow\infty} \langle x_{k_{j}}-\alpha x_{k_{j-1}}-\beta x_{n_{j-2}},x^*-v^* \rangle\notag\\
    =&\lim\limits_{j\rightarrow\infty} \langle x_{k}-\alpha x_{k-1}-\beta x_{k-2},x^*-v^* \rangle \notag\\
    =&\lim\limits_{j\rightarrow\infty} \langle x_{k_{m}}-\alpha x_{k_{m-1}}-\beta x_{k_{m-2}},x^*-v^* \rangle \notag\\
    =&\langle x^*-\alpha x^*-\beta x^*,x^*-v^* \rangle . 
  \end{align}
  Thus,
  \begin{equation}\label{llast}
    (1-\alpha-\beta)||x^*-v^*||^2 = 0.
  \end{equation}
  For $\beta\leq0<1-\alpha$, $1-\alpha-\beta \neq0$, we can conclude that $x^*=v^*$.

  Hence, we deduce that $\{x_{k}\}$ converges weakly to a point in $S_{D}$. This completes the proof.
